SELECT pcx.pcs_liam, sdm.liam FROM`ld-ds-bi-analytics-prod.product_catalog.products` sdm

-- accounts for those with leading zeros and those without. Will only join where found in both tables
INNER JOIN 

  (SELECT sap.pcs_liam, concat('SDM_0',sap.UPC) sdm_upc FROM sap

  UNION ALL

  SELECT sap.pcs_liam, concat('SDM_',sap.UPC) as sdm_upc FROM sap) pcx ON pcx.sdm_upc = sdm.liam

WHERE sdm.status = 'APPROVED'
